// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.llm.registryimport com.roshan.persona.brain.llm.provider.BuiltInCloudProvidersimport com.roshan.persona.brain.llm.provider.CloudProviderConfigimport com.roshan.persona.brain.llm.provider.CloudProviderConfig.Companion.CUSTOM_PREFIXimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport timber.log.Timberimport java.util.concurrent.ConcurrentHashMapimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Cloud provider registry. * * Single source of truth for all cloud LLM providers (built-in + user-added). * * ## Source Hierarchy * *   1. **Built-in providers** — defined in [BuiltInCloudProviders.ALL]. Always *      present, can be modified (e.g., user changes default model) but not deleted. * *   2. **User-added providers** — added at runtime via [addUserProvider]. Have *      IDs prefixed with [CloudProviderConfig.CUSTOM_PREFIX] (e.g., *      "custom_my-vllm"). Can be fully edited/deleted by the user. * * ## Persistence * * This in-memory implementation is for Module 2 standalone + tests. Real * persistence (Room-backed) ships in :feature:memory (Module 3) via the * `cloud_providers` table. * * The interface stays the same — brain code doesn't care about persistence. * * ## User Workflow * *   1. User opens Settings → AI Models → Cloud Providers *   2. Sees built-in providers (OpenAI, Anthropic, etc.) — all disabled *   3. Taps "Add Custom Provider" — enters URL, key, model name *   4. User taps "Test Connection" → [validateProviderCredentials] *   5. User enables the provider → [enableProvider] *   6. Brain's [com.roshan.persona.brain.llm.router.HybridLlmRouter] now *      considers this provider for cloud calls * * @see <a href="docs/spec/module2-spec-review.pdf">§8.2 Provider Registry</a> */@Singletonclass CloudProviderRegistry @Inject constructor() {    private val providersById = ConcurrentHashMap<String, CloudProviderConfig>()    init {        // Initialize with built-in providers (all disabled by default)        for (provider in BuiltInCloudProviders.ALL) {            providersById[provider.id] = provider        }    }    /**     * Get all providers (built-in + user-added), in display order.     *     * Order: built-in providers first (in [BuiltInCloudProviders.ALL] order),     * then user-added providers sorted alphabetically by display name.     */    fun getAll(): List<CloudProviderConfig> {        val builtIn = BuiltInCloudProviders.ALL.mapNotNull { providersById[it.id] }        val userAdded = providersById.values            .filter { !BuiltInCloudProviders.isBuiltIn(it.id) }            .sortedBy { it.displayName.lowercase() }        return builtIn + userAdded    }    /**     * Get all ENABLED providers (the ones the user has opted in for).     *     * Used by [com.roshan.persona.brain.llm.layer.CloudLlmLayer] to pick     * which providers to consider for cloud calls.     */    fun getEnabled(): List<CloudProviderConfig> = getAll().filter { it.isEnabled }    /**     * Get a single provider by ID.     *     * @return the provider config, or null if not found     */    fun getById(id: String): CloudProviderConfig? = providersById[id]    /**     * Add a new user-defined provider.     *     * The [config.id] MUST start with [CUSTOM_PREFIX] to distinguish from     * built-in providers. If the ID already exists, returns Failure.     *     * @return Success with the added config, or Failure if validation fails     */    fun addUserProvider(config: CloudProviderConfig): Result<CloudProviderConfig> {        val correlationId = CorrelationId.generate()        if (!config.id.startsWith(CUSTOM_PREFIX)) {            return Result.Failure(                error = AppError.Configuration.InvalidProviderConfig(                    reason = "User-added provider ID must start with '$CUSTOM_PREFIX', was: ${config.id}",                ),                correlationId = correlationId,                durationNanos = 0,            )        }        if (providersById.containsKey(config.id)) {            return Result.Failure(                error = AppError.Configuration.ProviderAlreadyExists(config.id),                correlationId = correlationId,                durationNanos = 0,            )        }        val withTimestamp = config.copy(            isBuiltIn = false,            updatedAtEpochMs = System.currentTimeMillis(),        )        providersById[config.id] = withTimestamp        Timber.tag("NOUS.L4").i(            "Added user provider: %s (%s) → %s",            withTimestamp.id,            withTimestamp.displayName,            withTimestamp.baseUrl,        )        return Result.Success(withTimestamp, correlationId, 0)    }    /**     * Update an existing provider's config.     *     * Built-in providers can be updated (e.g., change default model, add API     * key alias) but their [CloudProviderConfig.isBuiltIn] flag stays true.     *     * @return Success with the updated config, or Failure if not found     */    fun updateProvider(config: CloudProviderConfig): Result<CloudProviderConfig> {        val correlationId = CorrelationId.generate()        val existing = providersById[config.id]            ?: return Result.Failure(                error = AppError.Configuration.ProviderNotFound(config.id),                correlationId = correlationId,                durationNanos = 0,            )        // Preserve isBuiltIn flag — can't change it via update        val updated = config.copy(            isBuiltIn = existing.isBuiltIn,            updatedAtEpochMs = System.currentTimeMillis(),        )        providersById[config.id] = updated        Timber.tag("NOUS.L4").i("Updated provider: %s", updated.id)        return Result.Success(updated, correlationId, 0)    }    /**     * Delete a user-added provider.     *     * Built-in providers CANNOT be deleted — only disabled via [updateProvider].     *     * @return Success, or Failure if provider is built-in or not found     */    fun deleteUserProvider(id: String): Result<Unit> {        val correlationId = CorrelationId.generate()        val existing = providersById[id]            ?: return Result.Failure(                error = AppError.Configuration.ProviderNotFound(id),                correlationId = correlationId,                durationNanos = 0,            )        if (existing.isBuiltIn) {            return Result.Failure(                error = AppError.Configuration.ProviderBuiltinCannotDelete(id),                correlationId = correlationId,                durationNanos = 0,            )        }        providersById.remove(id)        Timber.tag("NOUS.L4").i("Deleted user provider: %s", id)        return Result.Success(Unit, correlationId, 0)    }    /**     * Enable a provider (user opt-in).     *     * Convenience method — equivalent to [updateProvider] with isEnabled=true.     */    fun enableProvider(id: String): Result<CloudProviderConfig> {        val existing = providersById[id]            ?: return Result.Failure(                error = AppError.Configuration.ProviderNotFound(id),                correlationId = CorrelationId.generate(),                durationNanos = 0,            )        return updateProvider(existing.copy(isEnabled = true))    }    /**     * Disable a provider (user opt-out).     */    fun disableProvider(id: String): Result<CloudProviderConfig> {        val existing = providersById[id]            ?: return Result.Failure(                error = AppError.Configuration.ProviderNotFound(id),                correlationId = CorrelationId.generate(),                durationNanos = 0,            )        return updateProvider(existing.copy(isEnabled = false))    }    /**     * Whether any cloud provider is enabled (used by privacy-mode checks).     */    fun hasAnyEnabled(): Boolean = providersById.values.any { it.isEnabled }    /**     * Number of enabled providers.     */    fun enabledCount(): Int = providersById.values.count { it.isEnabled }    /**     * Number of total providers (built-in + user-added).     */    fun totalCount(): Int = providersById.size}